//! Owner-local HTTP ingress for native portal-support commands.
use crate::domain::portal_support_commands::{AcknowledgeInput,CloseInput,RespondInput,request_invalid,source_changed};
use erpx_server_runtime::public::http_support::{HeaderMap,HeaderValue,IntoResponse,Json,Path,Request,Response,Router,State,StatusCode,body::to_bytes,header,post,serde_json};
use erpx_server_shared::public::{BusinessError,CommandKey,FailureKind,RecordId};
use serde_json::Value;
use std::collections::BTreeMap;
use std::{future::Future,pin::Pin,sync::Arc};
const BODY_LIMIT:usize=32*1024;const KEY_MAX:usize=200;
pub type SupportFuture<'a,T>=Pin<Box<dyn Future<Output=Result<T,BusinessError>>+Send+'a>>;
#[derive(Clone,Debug)]pub enum StaffCommand{Respond{request_id:String,input:RespondInput},Close{request_id:String,input:CloseInput}}
pub struct StaffRequest<'a>{pub host:&'a str,pub holding_slug:&'a str,pub headers:&'a HeaderMap,pub key:String,pub command:StaffCommand}
#[derive(Clone,Debug)]pub struct SupportReply{pub data:Value,pub context:Value}
impl SupportReply{pub fn value(self)->Value{serde_json::json!({"data":self.data,"context":self.context})}}
pub trait StaffBackend:Send+Sync{fn execute<'a>(&'a self,r:StaffRequest<'a>)->SupportFuture<'a,SupportReply>;}
pub struct SupportTarget{pub host:String,pub holding_slug:String,pub origin:String,pub backend:Arc<dyn StaffBackend>}
pub struct CustomerAckRequest<'a>{pub host:&'a str,pub holding_slug:&'a str,pub headers:&'a HeaderMap,pub key:String,pub request_id:String,pub input:AcknowledgeInput}
pub trait CustomerAckBackend:Send+Sync{fn execute<'a>(&'a self,r:CustomerAckRequest<'a>)->SupportFuture<'a,SupportReply>;}
pub struct CustomerTarget{pub host:String,pub holding_slug:String,pub origin:String,pub backend:Arc<dyn CustomerAckBackend>}
struct StaffState{targets:BTreeMap<(String,String),SupportTarget>}
struct CustomerState{targets:BTreeMap<(String,String),CustomerTarget>}
fn missing()->BusinessError{BusinessError::new(FailureKind::NotFound,"NOT_FOUND","Not found.")}
fn forbidden()->BusinessError{BusinessError::new(FailureKind::Forbidden,"ORIGIN_FORBIDDEN","Use the application origin.")}
fn key_required()->BusinessError{BusinessError::invalid("COMMAND_KEY_REQUIRED","Use a valid Idempotency-Key for this action.")}
fn unique<'a>(h:&'a HeaderMap,n:&str)->Result<Option<&'a str>,BusinessError>{let mut v=h.get_all(n).iter();let f=v.next();if v.next().is_some(){return Err(request_invalid())}f.map(|x|x.to_str().map_err(|_|request_invalid())).transpose()}
fn origin_ok(o:&str)->bool{o.strip_prefix("https://").is_some_and(|r|!r.is_empty()&&!r.bytes().any(|b|matches!(b,b'/'|b'?'|b'#'|b'@'|b':')))}
fn text<'a>(o:&'a serde_json::Map<String,Value>,k:&str)->Result<&'a str,BusinessError>{o.get(k).and_then(Value::as_str).ok_or_else(request_invalid)}
fn int(o:&serde_json::Map<String,Value>,k:&str,min:i64)->Result<i64,BusinessError>{o.get(k).and_then(Value::as_i64).filter(|v|*v>=min).ok_or_else(request_invalid)}
fn respond(body:&[u8])->Result<RespondInput,BusinessError>{let v:Value=serde_json::from_slice(body).map_err(|_|request_invalid())?;let o=v.as_object().filter(|o|o.len()==4&&["expectedBindingVersion","expectedResponseVersion","message","reason"].iter().all(|k|o.contains_key(*k))).ok_or_else(request_invalid)?;RespondInput{expected_binding_version:int(o,"expectedBindingVersion",1)?,expected_response_version:int(o,"expectedResponseVersion",0)?,message:text(o,"message")?.to_owned(),reason:text(o,"reason")?.to_owned()}.validate()}
fn close(body:&[u8])->Result<CloseInput,BusinessError>{let v:Value=serde_json::from_slice(body).map_err(|_|request_invalid())?;let o=v.as_object().filter(|o|o.len()==3&&["expectedBindingVersion","expectedResponseVersion","reason"].iter().all(|k|o.contains_key(*k))).ok_or_else(request_invalid)?;CloseInput{expected_binding_version:int(o,"expectedBindingVersion",1)?,expected_response_version:int(o,"expectedResponseVersion",0)?,reason:text(o,"reason")?.to_owned()}.validate()}
fn parse_ack(body:&[u8],request_id:&str)->Result<AcknowledgeInput,BusinessError>{let v:Value=serde_json::from_slice(body).map_err(|_|request_invalid())?;let o=v.as_object().ok_or_else(request_invalid)?;if o.get("action").and_then(Value::as_str)!=Some("acknowledge_support")||o.get("requestId").and_then(Value::as_str)!=Some(request_id)||!["bindingId","expectedBindingVersion","responseId","responseVersion"].iter().all(|k|o.contains_key(*k)){return Err(request_invalid())}let note=o.get("note").and_then(Value::as_str).unwrap_or_default();AcknowledgeInput{binding_id:text(o,"bindingId")?.to_owned(),expected_binding_version:int(o,"expectedBindingVersion",1)?,response_id:text(o,"responseId")?.to_owned(),response_version:int(o,"responseVersion",1)?,note:note.to_owned()}.validate()}
fn valid(v:&Value)->bool{v.as_object().is_some_and(|o|o.len()==6&&["id","requestId","bindingId","version","status","publishedAt"].iter().all(|k|o.contains_key(*k))&&o.get("id").and_then(Value::as_str).is_some_and(|s|!s.is_empty())&&o.get("requestId").and_then(Value::as_str).is_some_and(|s|!s.is_empty())&&o.get("bindingId").and_then(Value::as_str).is_some_and(|s|!s.is_empty())&&o.get("version").and_then(Value::as_i64).is_some_and(|n|n>=0)&&o.get("status").and_then(Value::as_str).is_some_and(|s|matches!(s,"published"|"acknowledged"|"closed_without_customer_acknowledgement"))&&o.get("publishedAt").and_then(Value::as_i64).is_some())}
fn valid_ack(v:&Value)->bool{v.as_object().is_some_and(|o|o.len()==7&&["id","requestId","bindingId","responseId","responseVersion","status","createdAt"].iter().all(|k|o.contains_key(*k))&&o.get("id").and_then(Value::as_str).is_some_and(|s|!s.is_empty())&&o.get("requestId").and_then(Value::as_str).is_some_and(|s|!s.is_empty())&&o.get("bindingId").and_then(Value::as_str).is_some_and(|s|!s.is_empty())&&o.get("responseId").and_then(Value::as_str).is_some_and(|s|!s.is_empty())&&o.get("responseVersion").and_then(Value::as_i64).is_some_and(|n|n>0)&&o.get("status").and_then(Value::as_str)==Some("acknowledged")&&o.get("createdAt").and_then(Value::as_i64).is_some_and(|n|n>=0))}
fn code(k:FailureKind)->StatusCode{match k{FailureKind::InvalidInput=>StatusCode::UNPROCESSABLE_ENTITY,FailureKind::Unauthenticated=>StatusCode::UNAUTHORIZED,FailureKind::Forbidden=>StatusCode::FORBIDDEN,FailureKind::NotFound=>StatusCode::NOT_FOUND,FailureKind::Conflict=>StatusCode::CONFLICT,FailureKind::Unavailable=>StatusCode::SERVICE_UNAVAILABLE}}
fn err(e:BusinessError)->Response{(code(e.kind),Json(serde_json::json!({"error":{"code":e.code,"message":e.message}}))).into_response()}
fn bounded(v:Value)->Response{let mut r=(StatusCode::OK,Json(v)).into_response();for(n,v)in[(header::CACHE_CONTROL,"private, no-store"),(header::REFERRER_POLICY,"no-referrer"),(header::X_CONTENT_TYPE_OPTIONS,"nosniff")]{r.headers_mut().insert(n,HeaderValue::from_static(v));}r}
fn target<'a,T>(map:&'a BTreeMap<(String,String),T>,host_slug:impl Fn(&T)->(&String,&String,&String),h:&'a HeaderMap,slug:&str)->Result<(&'a T,&'a str),BusinessError>{let host=unique(h,"host")?.filter(|v|!v.is_empty()).ok_or_else(missing)?;let t=map.get(&(host.to_owned(),slug.to_owned())).ok_or_else(missing)?;let(_,_,origin)=host_slug(t);if unique(h,"origin")?.is_some_and(|v|v!=origin){return Err(forbidden())}Ok((t,host))}
fn ct(h:&HeaderMap)->Result<(),BusinessError>{if unique(h,"content-type")?.ok_or_else(request_invalid)?.split(';').next().unwrap_or_default().trim().to_ascii_lowercase()!="application/json"{return Err(request_invalid())}Ok(())}
fn ck(h:&HeaderMap)->Result<String,BusinessError>{let raw=unique(h,"idempotency-key")?.filter(|v|!v.is_empty()).ok_or_else(key_required)?;let k=CommandKey::new(raw)?;if k.as_str().len()>KEY_MAX{return Err(request_invalid())}Ok(k.as_str().to_owned())}
impl StaffState{pub fn new(targets:Vec<SupportTarget>)->Result<Self,BusinessError>{let mut m=BTreeMap::new();for t in targets{if t.host.is_empty()||t.holding_slug.is_empty()||t.holding_slug.len()>128||!t.holding_slug.bytes().all(|b|b.is_ascii_lowercase()||b.is_ascii_digit()||matches!(b,b'_'|b'-'))||!origin_ok(&t.origin)||m.insert((t.host.clone(),t.holding_slug.clone()),t).is_some(){return Err(BusinessError::invalid("PORTAL_SUPPORT_HTTP_CONFIGURATION_INVALID","Use exact distinct registered Holding targets."))}}Ok(Self{targets:m})}}
async fn staff(state:Arc<StaffState>,h:&HeaderMap,slug:&str,id:&str,q:Option<&str>,body:&[u8],close_cmd:bool)->Response{let run=async{let(t,host)=target(&state.targets,|x|(&x.host,&x.holding_slug,&x.origin),h,slug)?;ct(h)?;let key=ck(h)?;let id=RecordId::new(id).map_err(|_|request_invalid())?.as_str().to_owned();if q.is_some_and(|v|!v.is_empty()){return Err(request_invalid())}if body.len()>BODY_LIMIT{return Err(request_invalid())}let command=if close_cmd{StaffCommand::Close{request_id:id,input:close(body)?}}else{StaffCommand::Respond{request_id:id,input:respond(body)?}};let r=t.backend.execute(StaffRequest{host,holding_slug:&t.holding_slug,headers:h,key,command}).await?;if !valid(&r.data)||!r.context.is_object(){return Err(source_changed())}Ok(r.value())};match run.await{Ok(v)=>bounded(v),Err(e)=>err(e)}}
impl CustomerState{pub fn new(targets:Vec<CustomerTarget>)->Result<Self,BusinessError>{let mut m=BTreeMap::new();for t in targets{if t.host.is_empty()||t.holding_slug.is_empty()||t.holding_slug.len()>128||!t.holding_slug.bytes().all(|b|b.is_ascii_lowercase()||b.is_ascii_digit()||matches!(b,b'_'|b'-'))||!origin_ok(&t.origin)||m.insert((t.host.clone(),t.holding_slug.clone()),t).is_some(){return Err(BusinessError::invalid("PORTAL_SUPPORT_HTTP_CONFIGURATION_INVALID","Use exact distinct registered Holding targets."))}}Ok(Self{targets:m})}}
async fn ack_handler(state:Arc<CustomerState>,h:&HeaderMap,slug:&str,id:&str,q:Option<&str>,body:&[u8])->Response{let run=async{let(t,host)=target(&state.targets,|x|(&x.host,&x.holding_slug,&x.origin),h,slug)?;ct(h)?;let key=ck(h)?;let id=RecordId::new(id).map_err(|_|request_invalid())?.as_str().to_owned();if q.is_some_and(|v|!v.is_empty()){return Err(request_invalid())}if body.len()>BODY_LIMIT{return Err(request_invalid())}let r=t.backend.execute(CustomerAckRequest{host,holding_slug:&t.holding_slug,headers:h,key,request_id:id.clone(),input:parse_ack(body,&id)?}).await?;if !valid_ack(&r.data)||!r.context.is_object(){return Err(source_changed())}Ok(r.value())};match run.await{Ok(v)=>bounded(v),Err(e)=>err(e)}}
pub fn portal_support_staff_router(targets:Vec<SupportTarget>)->Result<Router,BusinessError>{Ok(Router::new().route("/api/v1/holdings/{holding_slug}/customer-access/support/{request_id}/respond",post(respond_handler)).route("/api/v1/holdings/{holding_slug}/customer-access/support/{request_id}/close",post(close_handler)).with_state(Arc::new(StaffState::new(targets)?)))}
pub fn portal_support_customer_router(targets:Vec<CustomerTarget>)->Result<Router,BusinessError>{Ok(Router::new().route("/api/v1/portals/{holding_slug}/customer-access/support/{request_id}/acknowledge",post(ack_handler_route)).with_state(Arc::new(CustomerState::new(targets)?)))}
async fn respond_handler(State(s):State<Arc<StaffState>>,Path((slug,id)):Path<(String,String)>,r:Request)->Response{let(p,b)=r.into_parts();let b=match to_bytes(b,BODY_LIMIT+1).await{Ok(b)=>b,Err(_)=>return err(request_invalid())};staff(s,&p.headers,&slug,&id,p.uri.query(),&b,false).await}
async fn close_handler(State(s):State<Arc<StaffState>>,Path((slug,id)):Path<(String,String)>,r:Request)->Response{let(p,b)=r.into_parts();let b=match to_bytes(b,BODY_LIMIT+1).await{Ok(b)=>b,Err(_)=>return err(request_invalid())};staff(s,&p.headers,&slug,&id,p.uri.query(),&b,true).await}
async fn ack_handler_route(State(s):State<Arc<CustomerState>>,Path((slug,id)):Path<(String,String)>,r:Request)->Response{let(p,b)=r.into_parts();let b=match to_bytes(b,BODY_LIMIT+1).await{Ok(b)=>b,Err(_)=>return err(request_invalid())};ack_handler(s,&p.headers,&slug,&id,p.uri.query(),&b).await}
